CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email varchar(320) NOT NULL UNIQUE,password_hash text NOT NULL,display_name varchar(80) NOT NULL,state varchar(24) NOT NULL DEFAULT 'active' CHECK (state IN ('active','pending_deletion','deleted')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hunter_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,hunter_name varchar(40) NOT NULL,level integer NOT NULL DEFAULT 1 CHECK (level >= 1),rank varchar(1) NOT NULL DEFAULT 'E' CHECK (rank IN ('E','D','C','B','A','S')),xp bigint NOT NULL DEFAULT 0 CHECK (xp >= 0),streak integer NOT NULL DEFAULT 0 CHECK (streak >= 0),version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS refresh_tokens (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,digest char(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS refresh_tokens_user_idx ON refresh_tokens(user_id);
CREATE TABLE IF NOT EXISTS sync_events (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,device_id uuid NOT NULL,aggregate_type varchar(40) NOT NULL,aggregate_id uuid NOT NULL,sequence bigint NOT NULL CHECK (sequence >= 1),occurred_at timestamptz NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(aggregate_type, aggregate_id, sequence));
CREATE INDEX IF NOT EXISTS sync_events_user_cursor_idx ON sync_events(user_id, received_at, id);
